package java.util.concurrent;
import java.util.ArrayList;
import java.util.function.*;
public class CompletableFuture<T> implements Future<T>, CompletionStage<T> {
 private T value; private Throwable failure; private boolean done,cancelled; private final ArrayList<Runnable> actions=new ArrayList<Runnable>();
 private void listen(Runnable r){if(done)r.run();else actions.add(r);} private void finish(){ArrayList<Runnable> a=new ArrayList<Runnable>(actions);actions.clear();for(Runnable r:a)r.run();}
 public CompletableFuture<T> toCompletableFuture(){return this;}
 public boolean complete(T v){if(done)return false;value=v;done=true;finish();return true;}
 public boolean completeExceptionally(Throwable t){if(t==null)throw new NullPointerException();if(done)return false;failure=t;done=true;finish();return true;}
 public boolean cancel(boolean b){if(done)return false;cancelled=true;failure=new CancellationException();done=true;finish();return true;} public boolean isCancelled(){return cancelled;} public boolean isDone(){return done;} public boolean isCompletedExceptionally(){return done&&failure!=null;}
 public T get()throws InterruptedException,ExecutionException {java.lang.VMThread.runPending();if(cancelled)throw (CancellationException)failure;if(failure!=null)throw new ExecutionException(failure);return value;}
 public T get(long n,TimeUnit u)throws InterruptedException,ExecutionException,TimeoutException {if(u==null)throw new NullPointerException();java.lang.VMThread.runPending();if(!done)throw new TimeoutException();return get();}
 public T join(){java.lang.VMThread.runPending();if(cancelled)throw (CancellationException)failure;if(failure!=null)throw failure instanceof CompletionException?(CompletionException)failure:new CompletionException(failure);return value;}
 public static <U> CompletableFuture<U> completedFuture(U value){CompletableFuture<U> f=new CompletableFuture<U>();f.complete(value);return f;}
 public static <U> CompletableFuture<U> supplyAsync(Supplier<U> s){return supplyAsync(s,new Executor(){public void execute(Runnable r){new Thread(r).start();}});} public static <U> CompletableFuture<U> supplyAsync(final Supplier<U> s,Executor e){if(s==null||e==null)throw new NullPointerException();final CompletableFuture<U> f=new CompletableFuture<U>();e.execute(new Runnable(){public void run(){try{f.complete(s.get());}catch(Throwable t){f.completeExceptionally(t);}}});return f;}
 public static CompletableFuture<Void> runAsync(Runnable r){return runAsync(r,new Executor(){public void execute(Runnable x){new Thread(x).start();}});} public static CompletableFuture<Void> runAsync(final Runnable r,Executor e){if(r==null||e==null)throw new NullPointerException();return supplyAsync(new Supplier<Void>(){public Void get(){r.run();return null;}},e);}
 public <U> CompletableFuture<U> thenApply(final Function<? super T,? extends U> fn){if(fn==null)throw new NullPointerException();final CompletableFuture<U> out=new CompletableFuture<U>();listen(new Runnable(){public void run(){if(failure!=null)out.completeExceptionally(failure);else try{out.complete(fn.apply(value));}catch(Throwable t){out.completeExceptionally(t);}}});return out;}
 public CompletableFuture<Void> thenAccept(final Consumer<? super T> fn){if(fn==null)throw new NullPointerException();return thenApply(new Function<T,Void>(){public Void apply(T v){fn.accept(v);return null;}});}
 public <U> CompletableFuture<U> thenCompose(final Function<? super T,? extends CompletionStage<U>> fn){if(fn==null)throw new NullPointerException();final CompletableFuture<U> out=new CompletableFuture<U>();listen(new Runnable(){public void run(){if(failure!=null){out.completeExceptionally(failure);return;}try{final CompletableFuture<U> next=fn.apply(value).toCompletableFuture();next.listen(new Runnable(){public void run(){if(next.failure!=null)out.completeExceptionally(next.failure);else out.complete(next.value);}});}catch(Throwable t){out.completeExceptionally(t);}}});return out;}
 public <U,V> CompletableFuture<V> thenCombine(final CompletionStage<? extends U> stage,final BiFunction<? super T,? super U,? extends V> fn){if(stage==null||fn==null)throw new NullPointerException();final CompletableFuture<? extends U> other=stage.toCompletableFuture();final CompletableFuture<V> out=new CompletableFuture<V>();final Runnable action=new Runnable(){public void run(){if(!done||!other.done||out.done)return;if(failure!=null)out.completeExceptionally(failure);else if(other.failure!=null)out.completeExceptionally(other.failure);else try{out.complete(fn.apply(value,other.value));}catch(Throwable t){out.completeExceptionally(t);}}};listen(action);other.listen(action);return out;}
 public CompletableFuture<T> exceptionally(final Function<Throwable,? extends T> fn){if(fn==null)throw new NullPointerException();final CompletableFuture<T> out=new CompletableFuture<T>();listen(new Runnable(){public void run(){try{out.complete(failure==null?value:fn.apply(failure));}catch(Throwable t){out.completeExceptionally(t);}}});return out;}
 public <U> CompletableFuture<U> handle(final BiFunction<? super T,Throwable,? extends U> fn){if(fn==null)throw new NullPointerException();final CompletableFuture<U> out=new CompletableFuture<U>();listen(new Runnable(){public void run(){try{out.complete(fn.apply(value,failure));}catch(Throwable t){out.completeExceptionally(t);}}});return out;}
 public CompletableFuture<T> whenComplete(final BiConsumer<? super T,? super Throwable> fn){if(fn==null)throw new NullPointerException();final CompletableFuture<T> out=new CompletableFuture<T>();listen(new Runnable(){public void run(){try{fn.accept(value,failure);if(failure!=null)out.completeExceptionally(failure);else out.complete(value);}catch(Throwable t){out.completeExceptionally(failure!=null?failure:t);}}});return out;}
 public static CompletableFuture<Void> allOf(final CompletableFuture<?>... fs){if(fs==null)throw new NullPointerException();final CompletableFuture<Void> out=new CompletableFuture<Void>();final Runnable r=new Runnable(){public void run(){for(CompletableFuture<?> f:fs)if(!f.done)return;for(CompletableFuture<?> f:fs)if(f.failure!=null){out.completeExceptionally(f.failure);return;}out.complete(null);}};for(CompletableFuture<?> f:fs){if(f==null)throw new NullPointerException();}for(CompletableFuture<?> f:fs)f.listen(r);r.run();return out;}
 public static CompletableFuture<Object> anyOf(final CompletableFuture<?>... fs){if(fs==null)throw new NullPointerException();final CompletableFuture<Object> out=new CompletableFuture<Object>();for(CompletableFuture<?> f:fs)if(f==null)throw new NullPointerException();for(final CompletableFuture<?> f:fs)f.listen(new Runnable(){public void run(){if(f.failure!=null)out.completeExceptionally(f.failure);else out.complete(f.value);}});return out;}
}
